  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky (blue)
  brush.fill("#87CEEB", 255); // Blue sky
  brush.beginShape(curvature);
  brush.vertex(0, 200);     // Top left
  brush.vertex(200, 200);   // Center
  brush.vertex(400, 200);   // Top right
  brush.endShape(true);

  // Green hills
  brush.fill("#006400", 200); // Green hills
  brush.beginShape(curvature);
  brush.vertex(0, 250);     // Left hill
  brush.vertex(100, 280);   // Middle hill
  brush.vertex(200, 300);   // Higher hill
  brush.vertex(300, 280);   // Lower hill
  brush.endShape(true);

  // Sun (yellow)
  brush.fill("#FFD700", 200); // Yellow sun
  brush.beginShape(curvature);
  brush.vertex(150, 150);   // Sun position
  brush.vertex(170, 130);   // Sun disk
  brush.vertex(190, 110);   // Sun disk
  brush.endShape(true);
}
```

